# Tekenvlak van een gevuld symbool, als het geen 24x24 is. Het WhatsApp-glyph houdt
# zijn eigen 720-raster; de marge eromheen is de vrije ruimte die het merk vraagt en
# zet het optisch op dezelfde grootte als de lijniconen.
VOLBOX = {"huisje": "0 0 24 23", "whatsapp": "-72 -72 864 864", "whatsapp-wit": "-72 -72 864 864",
          "ster": SOLAR_VIEWBOX}

# De ster vult het 24-raster niet helemaal: de tekening loopt van 2 tot 22 (Solar star-bold, gemeten met
# getBBox). Een deels gevulde ster knipt op dat vlak, anders oogt 4,9 meteen als een volle vijf. De knip
# staat in de maat van de buitenste svg (0 0 24 24), dus met de zoom van SOLAR_VIEWBOX erin.
STER_LINKS = round((2.0 - SOLAR_MARGE) * 24 / SOLAR_VLAK, 3)    # 0,5
STER_BREED = round(20.0 * 24 / SOLAR_VLAK, 3)                   # 23,0


def googlecijfer():
    """De Google-score uit config als getal. In de kopij staat hij met een komma."""
    try:
        return float(str(cfg.GOOGLE_SCORE).replace(",", "."))
    except ValueError:
        raise BouwFout(f"GOOGLE_SCORE '{cfg.GOOGLE_SCORE}' is geen cijfer")


# Diensticonen, per dienstsleutel (anker). Solar heeft geen verhuislift: die is zelf getekend in dezelfde
# logica, op hetzelfde 24-raster met rondingen van 1,25 tot 2 en balken van 1,5: de ladder als vlak in de
